export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const tTop = launchSpeed / gravity;
  const yTop = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;
  const tossedHeight = Math.max(0, launchSpeed * t - 0.5 * gravity * t * t);

  let dropVelocity = 0;
  let dropAcceleration = 0;
  let dropHeight = yTop;

  const isReleased = t >= tTop;
  if (isReleased) {
    const dt = t - tTop;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
    dropHeight = Math.max(0, yTop - 0.5 * gravity * dt * dt);
  }

  let tossState = 'At launch';
  if (t < tTop) {
    tossState = 'Rising';
  } else if (Math.abs(t - tTop) < 0.02) {
    tossState = 'At the top';
  } else if (tossedHeight > 0) {
    tossState = 'Falling';
  } else {
    tossState = 'At launch height';
  }

  let dropState = 'Held in place';
  if (Math.abs(t - tTop) < 0.02) {
    dropState = 'Just released';
  } else if (isReleased) {
    if (dropHeight > 0) {
      dropState = 'Falling together';
    } else {
      dropState = 'At launch height';
    }
  }

  const yMin = 0;
  const yMax = 2.2;
  const pxPerM = 260 / (yMax - yMin);
  const yBasePx = 360;

  const tossYPx = yBasePx - (tossedHeight - yMin) * pxPerM;
  const dropYPx = yBasePx - (dropHeight - yMin) * pxPerM;
  const topYPx = yBasePx - (yTop - yMin) * pxPerM;

  const tossX = 160;
  const dropX = 480;

  const objects = [];

  objects.push(...sdk.panel({ x: 20, y: 30, w: 280, h: 360, title: 'Toss lane', state: tossState, id: 'lane.toss' }));
  objects.push(...sdk.panel({ x: 340, y: 30, w: 280, h: 360, title: 'Drop lane', state: dropState, id: 'lane.drop' }));

  objects.push(sdk.axis('axis.toss', { x: 50, y: yBasePx, length: 260, orientation: 'y', min: yMin, max: yMax, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: 'Height', unit: 'm' }));
  objects.push(sdk.axis('axis.drop', { x: 370, y: yBasePx, length: 260, orientation: 'y', min: yMin, max: yMax, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: 'Height', unit: 'm' }));

  objects.push(...sdk.gate('gate', dropX, topYPx, { open: isReleased, label: 'Release gate' }));

  if (isReleased) {
    objects.push(sdk.circle('outline.toss', tossX, topYPx, 24, { opacity: 0.3 }));
    objects.push(sdk.circle('outline.drop', dropX, topYPx, 24, { opacity: 0.3 }));
  }

  objects.push(sdk.circle('ball.toss', tossX, tossYPx, 24));
  objects.push(sdk.circle('ball.drop', dropX, dropYPx, 24));

  const vScale = 20;
  const aScale = 5;

  objects.push(...sdk.vector('vec.v.toss', { x: tossX - 25, y: tossYPx }, { value: tossedVelocity, direction: 'up' }, { scale: vScale, label: 'v' }));
  objects.push(...sdk.vector('vec.v.drop', { x: dropX - 25, y: dropYPx }, { value: dropVelocity, direction: 'up' }, { scale: vScale, label: 'v' }));

  objects.push(...sdk.vector('vec.a.toss', { x: tossX + 25, y: tossYPx }, { value: tossedAcceleration, direction: 'up' }, { scale: aScale, label: 'a' }));
  objects.push(...sdk.vector('vec.a.drop', { x: dropX + 25, y: dropYPx }, { value: dropAcceleration, direction: 'up' }, { scale: aScale, label: 'a' }));

  objects.push(...sdk.callout(tossX + 45, tossYPx - 20, [`v: ${sdk.format(tossedVelocity, 2)} m/s`, `a: ${sdk.format(tossedAcceleration, 2)} m/s²`], { id: 'callout.toss' }));
  objects.push(...sdk.callout(dropX + 45, dropYPx - 20, [`v: ${sdk.format(dropVelocity, 2)} m/s`, `a: ${sdk.format(dropAcceleration, 2)} m/s²`], { id: 'callout.drop' }));

  const frame = sdk.frame(objects, {
    width: 640,
    height: 420,
    readouts: [
      { id: 'tossedVelocity', value: tossedVelocity },
      { id: 'tossedAcceleration', value: tossedAcceleration },
      { id: 'dropVelocity', value: dropVelocity },
      { id: 'dropAcceleration', value: dropAcceleration }
    ]
  });

  const quantities = {
    launchSpeed,
    gravity,
    apexTime: tTop,
    apexHeight: yTop,
    tossedVelocity,
    tossedAcceleration,
    tossedHeight,
    dropVelocity,
    dropAcceleration,
    dropHeight
  };

  return { frame, quantities };
}
